import java.util.*;

class Solution {
    public List<List<String>> suggestedProducts(String[] products, String searchWord) {
        Arrays.sort(products);
        List<List<String>> result = new ArrayList<>();
        int start = 0, end = products.length - 1;

        for (int i = 0; i < searchWord.length(); i++) {
            char c = searchWord.charAt(i);
            // Move start forward if product at start doesn't match prefix
            while (start <= end && (products[start].length() <= i || products[start].charAt(i) != c)) {
                start++;
            }
            // Move end backward if product at end doesn't match prefix
            while (start <= end && (products[end].length() <= i || products[end].charAt(i) != c)) {
                end--;
            }

            List<String> suggestions = new ArrayList<>();
            int remain = Math.min(3, end - start + 1);
            for (int j = 0; j < remain; j++) {
                suggestions.add(products[start + j]);
            }
            result.add(suggestions);
        }

        return result;
    }
}

